/**
 * Generic, cross-entity "what the pull couldn't resolve" mechanism.
 *
 * Every pull flow (automation, skill, flow, agent, …) threads a single
 * `MissingDataCollector` through its stages. Each stage records what
 * it couldn't resolve — an aspect antman returned 404 for, a field ref
 * that wasn't in any app's field bag, a task type this EDK version
 * doesn't support, a missing AI provider connector, whatever. The
 * orchestrator snapshots the collector at the end and surfaces the
 * report alongside the file paths it wrote.
 *
 * The design principle: never abort a pull because one piece of data
 * is missing. Deliver every file the collected data supports, and
 * hand the agent a structured report so it can tell the user
 * precisely what's missing and why. Broken imports, fabricated
 * handles, and silent omissions are all ruled out by construction —
 * callers must either (a) emit real data from the catalog or (b)
 * record a miss and degrade the output honestly.
 *
 * `MissingCategory` is a flat string union. Top-level entity misses
 * reuse `EdkEntityType` directly (a missing aspect is `"aspect"`, a
 * missing referenced skill is `"skill"`); other misses use bare
 * strings (`"task"`, `"trigger"`, `"fieldRef"`, `"valueRef"`). A
 * compile-time check below guards against drift — if `EdkEntityType`
 * ever gains a value that overlaps with the bare strings, the build
 * fails.
 */
import type { EdkEntityType } from "../fs/entity.js";
/**
 * Closed set of category labels for missed data. Top-level entity
 * misses reuse `EdkEntityType`; everything else uses bare strings.
 */
export type MissingCategory = EdkEntityType | "task" | "trigger" | "fieldRef" | "valueRef" | "stage" | "displayBlock";
/**
 * A single item of data the pull flow couldn't resolve. Generic
 * across entity types so every pull can report its own categories
 * without adding new machinery.
 */
export interface MissingItem {
    /** What kind of thing is missing. Closed union — see `MissingCategory`. */
    readonly category: MissingCategory;
    /**
     * The unresolved identifier. Usually a UUID, sometimes a refKey or
     * type name (e.g. a `WorkflowTaskType` we don't support).
     */
    readonly id: string;
    /**
     * Human-readable explanation of why the item couldn't be resolved.
     * Surfaces in the agent-facing output; write it as something the
     * agent can relay to a user without translation.
     */
    readonly reason: string;
    /**
     * Optional: where in the source entity the miss occurred — a task
     * refKey, `"trigger"`, `"automation owner"`, etc. Helps the agent
     * point the user at the right part of the pulled bundle.
     */
    readonly context?: string;
}
/**
 * Snapshot of everything the pull couldn't resolve. Returned from the
 * orchestrator as part of the `PullResult`.
 */
export interface MissingDataReport {
    readonly items: readonly MissingItem[];
    /** True iff no items were recorded — the pull completed cleanly. */
    readonly isEmpty: boolean;
}
/**
 * Mutable collector threaded through a single pull call. Every stage
 * (`buildAppCatalog`, `deserializeAutomation`, the printer) receives
 * the same instance and appends to it; the orchestrator snapshots via
 * `build()` just before returning.
 */
export declare class MissingDataCollector {
    private readonly items;
    record(item: MissingItem): void;
    build(): MissingDataReport;
}
/** An empty report, useful as a default in call sites that don't collect. */
export declare const EMPTY_MISSING_REPORT: MissingDataReport;
